// WaitForNoShadowBranches polls until all shadow branches are cleaned up or
// the timeout expires. Shadow branch cleanup can lag slightly behind checkpoint
// condensation (carry-forward creates intermediate branches that are deleted
// asynchronously).
//
// If shadow branches persist after half the timeout, this helper commits any
// remaining untracked/modified files (e.g., agent-internal config files like
// opencode's .opencode/ directory) to trigger a final condensation + cleanup.
func WaitForNoShadowBranches(t *testing.T, dir string, timeout time.Duration) {
	t.Helper()
	halfDeadline := time.Now().Add(timeout / 2)
	committed := false

	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		shadow := shadowBranches(t, dir)
		if len(shadow) == 0 {
			return
		}
		// If shadow branches persist past the halfway point, try committing
		// remaining agent-internal files to trigger full cleanup.
		if !committed && time.Now().After(halfDeadline) {
			status := gitOutputSafe(dir, "status", "--porcelain")
			if strings.TrimSpace(status) != "" {
				_ = exec.Command("git", "-C", dir, "add", "-A").Run()
				_ = exec.Command("git", "-C", dir, "commit", "--no-gpg-sign", "-m", "test: commit remaining agent files").Run()
				committed = true
			}
		}
		time.Sleep(200 * time.Millisecond)
	}
	shadow := shadowBranches(t, dir)
	assert.Empty(t, shadow,
		"shadow branches should be cleaned up after commit, found: %v", shadow)
}

