// TryWaitForCheckpoint is like WaitForCheckpoint but returns an error instead
// of calling t.Fatalf. Useful when a fallback path can still produce a
// checkpoint (e.g., committing remaining files after a mid-turn commit race).
func TryWaitForCheckpoint(t *testing.T, s *RepoState, timeout time.Duration) error {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		after := GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")
		if after != s.CheckpointBefore {
			return nil
		}
		time.Sleep(200 * time.Millisecond)
	}
	return fmt.Errorf("checkpoint branch did not advance within %s", timeout)
}

